    {
      "topic_zh": "价格条款",
      "value": "要求提供FOB宁波报价",
      "quote": "FOB寧波でのお見積り"
    },
    {
      "topic_zh": "交期",
      "value": "询问能否在12月中旬前交付，未说明年份及交付节点",
      "quote": "12月中旬までの納期可否"
