    {
      "signal_zh": "明确提供公司名称、所在地、进口商身份及联系人",
      "positive": true,
      "quote": "東京の家電輸入商社、山田商事の佐藤と申します"
    },
    {
      "signal_zh": "明确指定产品型号",
      "positive": true,
      "quote": "4.5Lデジタルエアフライヤー（AF-45D）"
